template <typename T>
struct ProcessorTraits {
    // 1. Conditional Type Deduction based on Type Trait
    // If T is integral, use ptrdiff_t for indexing. Otherwise, use T.
    using IndexType = typename std::conditional<
        std::is_integral_v<T>,
        ptrdiff_t,
        T
    >::type;

    IndexType data;

    // 2. SFINAE/Trait check using specialization (e.g., enable_if)
    template <typename U = T>
    typename std::enable_if_t<std::is_integral_v<U>, IndexType>
    get_index_safe(U val) { return val; }

    // 3. Deduction using decltype for return type based on member types
    template <typename V>
    auto calculate(V v) -> decltype(data + v);
};

